paired_artifact_parity.command:
node --input-type=module <<'NODE'
import * as esbuild from 'esbuild';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
const h=x=>createHash('sha256').update(x).digest('hex');
const manifest=JSON.parse(fs.readFileSync('docs/remediation/evidence/W20.06/artifact.json'));
const worker=JSON.parse(fs.readFileSync('docs/remediation/evidence/W20.06/worker.json'));
const version=fs.readFileSync('src/sdk/version.ts','utf8').match(/'([^']+)'/)[1];
const banner=`/* edge-personalization SDK v${version} — one package: core (identity, transport), emit (four capture paths), listen (decisions). */`;
const results=[];
for(const [entry,out,format] of [['src/sdk/index.ts','public/sdk/edge-personalization.esm.js','esm'],['src/sdk/browser.ts','public/sdk/edge-personalization.js','iife']]){
 const r=await esbuild.build({entryPoints:[path.resolve(entry)],outfile:path.resolve(out),bundle:true,platform:'browser',target:'es2022',minify:false,sourcemap:false,legalComments:'none',logLevel:'silent',metafile:true,banner:{js:banner},format,write:false});
 const generated=r.outputFiles[0].contents,current=fs.readFileSync(out);
 const inputs=Object.keys(r.metafile.inputs).map(p=>({path:p,sha256:h(fs.readFileSync(p))}));
 const unpinned=inputs.filter(x=>!manifest.files.some(y=>x.path===y.path&&x.sha256===y.sha256));
 const w=worker.bundle_generation.artifacts.find(x=>x.path===out);
 results.push({path:out,format,bytes:generated.length,generated_sha256:h(generated),current_sha256:h(current),exact_bytes:Buffer.from(generated).equals(current),worker_hash_matches:w.generated_sha256===h(generated),input_count:inputs.length,unpinned,write:false});
}
console.log(JSON.stringify({at:new Date().toISOString(),results},null,2));
if(results.some(x=>!x.exact_bytes||!x.worker_hash_matches||x.unpinned.length))process.exit(1);
NODE
